def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    tree = [0] * (len(ranks) + 1)
    result = []

    for i, value in enumerate(a):
        if i > k:
            rank = ranks[a[i - k - 1]]
            while rank < len(tree):
                tree[rank] -= 1
                rank += rank & -rank

        rank = ranks[value]
        count_leq = 0
        while rank:
            count_leq += tree[rank]
            rank -= rank & -rank

        result.append(min(i, k) - count_leq)

        rank = ranks[value]
        while rank < len(tree):
            tree[rank] += 1
            rank += rank & -rank

    return result
